function check(graph,source){if(!Array.isArray(graph)||!Number.isInteger(source)||source<0||source>=graph.length||graph.some(edges=>!Array.isArray(edges)||edges.some(([to,w])=>!Number.isInteger(to)||to<0||to>=graph.length||!Number.isFinite(w)||w<0)))throw new TypeError('Nonnegative weighted adjacency lists and valid source required');}
export function bfsTrace(graph,source){check(graph,source);const distance=Array(graph.length).fill(null),parent=Array(graph.length).fill(null),queue=[source],processed=[];distance[source]=0;const frames=[];const save=(current,message)=>frames.push({current,message,distance:[...distance],parent:[...parent],queue:[...queue],processed:[...processed]});save(null,'Mark the source when enqueuing it; its edge-count distance is zero.');while(queue.length){const node=queue.shift();for(const [to]of graph[node])if(distance[to]===null){distance[to]=distance[node]+1;parent[to]=node;queue.push(to);}processed.push(node);save(node,`Process vertex ${node}; enqueue each newly discovered neighbor once. Distances count edges, not edge weights.`);}return frames;}
export function dijkstraTrace(graph,source){check(graph,source);const distance=Array(graph.length).fill(Infinity),parent=Array(graph.length).fill(null),settled=[],queue=[[0,source]],frames=[];distance[source]=0;const save=(current,edge,message)=>frames.push({current,edge,message,distance:[...distance],parent:[...parent],settled:[...settled],queue:queue.map(x=>[...x])});save(null,null,'Source distance is zero; all other tentative distances are infinity.');while(queue.length){queue.sort((a,b)=>a[0]-b[0]||a[1]-b[1]);const [d,node]=queue.shift();if(d!==distance[node]){save(node,null,`Discard stale entry (${d}, vertex ${node}); its current tentative distance is ${distance[node]}.`);continue;}settled.push(node);save(node,null,`Settle vertex ${node} at distance ${d}. Nonnegative edges make this current minimum final.`);for(const [to,w]of graph[node]){const candidate=d+w,improves=candidate<distance[to];if(improves){distance[to]=candidate;parent[to]=node;queue.push([candidate,to]);}save(node,[node,to],`Relax ${node}→${to}: ${d}+${w}=${candidate}. ${improves?'Improve the tentative distance and enqueue a fresh entry.':'No improvement; leave its distance unchanged.'}`);}}return frames;}
